 arr=np.array([row[a:b] for row in grid[2:27]])
 scores=[]
 for pr in range(1,13):
  for pc in range(1,7):
   mismatch=0
   for i in range(arr.shape[0]):
    for j in range(arr.shape[1]):
     vals=[arr[ii,jj] for ii in range(i%pr,arr.shape[0],pr) for jj in range(j%pc,arr.shape[1],pc)]
     mismatch+= arr[i,j]!=collections.Counter(vals).most_common(1)[0][0]
   scores.append((mismatch,pr,pc))
 print(sorted(scores)[:8])

def period_repair(arr,pr,pc):
 pred=arr.copy(); dif=[]
 for i in range(arr.shape[0]):
  for j in range(arr.shape[1]):
   vals=[arr[ii,jj] for ii in range(i%pr,arr.shape[0],pr) for jj in range(j%pc,arr.shape[1],pc)]
   counts=collections.Counter(vals)
   # ties
   pred[i,j]=counts.most_common(1)[0][0]
   if pred[i,j]!=arr[i,j]: dif.append((i,j,arr[i,j],pred[i,j],counts))
 return pred,dif
for name,(a,b),p in [('A',(1,7),(3,5)),('B',(8,14),(6,5)),('C',(15,21),(4,5)),('D',(22,28),(4,5))]:
 arr=np.array([row[a:b] for row in grid[2:27]])
 pred,dif=period_repair(arr,*p)
 print(name,[(i+2,j+a,v,w,counts) for i,j,v,w,counts in dif])
